// Shape of the module generated by the sfxWasm esbuild plugin (@hpcc-js/esbuild-plugins/sfx-wrapper).
declare module "*.wasm" {
    export class WasmModuleResource<M = unknown> implements Disposable {
        readonly ready: Promise<M>;
        readonly instance: M | undefined;
        dispose(): void;
        [Symbol.dispose](): void;
    }
}
